:root {
  --parchment: #f0e8d0;
  --parchment-dark: #ddd0a8;
  --ink: #2c2416;
  --ink-mid: #5a4a30;
  --ink-light: #8a7455;
  --accent-red: #9b2c2c;
  --accent-green: #2d6a4f;
  --accent-blue: #2c4a7a;
  --border: #b8a07a;
  --tag-bg: #e8d8b0;
}

article.transit-log {
  background-color: var(--parchment);
  border: 2px solid var(--border);
  border-radius: 4px;
  width: 480px;
  padding: 0;
  font-size: 13px;
  color: var(--ink);
  overflow: hidden;
}

.log-header {
  background-color: var(--ink);
  padding: 10px 16px;
  display: flex;
  align-items: center;
  gap: 12px;
  border-bottom: 3px solid var(--accent-red);
}

.log-badge {
  background-color: var(--accent-red);
  color: var(--parchment);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.12em;
  padding: 3px 7px;
  border-radius: 2px;
  flex-shrink: 0;
}

.log-title {
  font-size: 17px;
  font-weight: 700;
  color: var(--parchment);
  margin: 0;
  letter-spacing: 0.03em;
  flex: 1;
}

.log-subtitle {
  font-size: 11px;
  color: var(--ink-light);
  margin: 0;
  letter-spacing: 0.06em;
  flex-shrink: 0;
}

.log-body {
  padding: 14px 16px;
  border-bottom: 1px solid var(--border);
}

.log-grid {
  display: grid;
  grid-template-columns: 72px 1fr 1fr;
  gap: 12px;
  align-items: start;
}

.instrument-icon {
  position: relative;
  width: 64px;
  height: 64px;
  margin: 0;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}

.icon-ring {
  position: absolute;
  border-radius: 50%;
  border: 2px solid var(--ink-mid);
}

.icon-ring.outer {
  width: 56px;
  height: 56px;
  border-color: var(--ink);
}

.icon-ring.inner {
  width: 32px;
  height: 32px;
  border-color: var(--accent-blue);
  border-width: 1.5px;
}

.icon-crosshair {
  position: absolute;
  background-color: var(--ink-mid);
}

.icon-crosshair.h {
  width: 48px;
  height: 1px;
}

.icon-crosshair.v {
  width: 1px;
  height: 48px;
}

.readings {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.reading-row {
  display: flex;
  flex-direction: column;
  gap: 1px;
  border-bottom: 1px dashed var(--parchment-dark);
  padding-bottom: 5px;
}

.reading-row:last-child {
  border-bottom: none;
  padding-bottom: 0;
}

.reading-label {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--ink-light);
  text-transform: uppercase;
}

.reading-value {
  font-size: 13px;
  font-weight: 600;
  color: var(--ink);
  letter-spacing: 0.02em;
}

.meta-col {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.meta-item {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.meta-label {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--ink-light);
  text-transform: uppercase;
}

.meta-val {
  font-size: 12px;
  font-weight: 500;
  color: var(--ink);
}

.status-pill {
  margin-top: 4px;
  display: inline-block;
  background-color: var(--accent-green);
  color: var(--parchment);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 3px 9px;
  border-radius: 10px;
  align-self: flex-start;
}

.log-footer {
  background-color: var(--tag-bg);
  padding: 8px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.footer-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  list-style: none;
  margin: 0;
  padding: 0;
}

.tag {
  background-color: var(--parchment);
  border: 1px solid var(--border);
  border-radius: 3px;
  font-size: 10px;
  font-weight: 600;
  color: var(--ink-mid);
  padding: 2px 7px;
  letter-spacing: 0.04em;
}

.log-ref {
  font-size: 10px;
  color: var(--ink-light);
  letter-spacing: 0.06em;
  font-style: italic;
}
